<?php require_once __DIR__.'/../includes/auth.php';$pageTitle='Inventory';$base='/shop-inventory-management';$q=trim($_GET['q']??'');$status=$_GET['status']??'';$where=[];$args=[];if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if($status==='low')$where[]='p.quantity<=p.minimum_stock AND p.quantity>0';elseif($status==='out')$where[]='p.quantity=0';$sql='SELECT p.id,p.name,p.sku,p.quantity,p.minimum_stock,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY (p.quantity=0) DESC,(p.quantity<=p.minimum_stock) DESC,p.name';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$moves=$pdo->query('SELECT sm.*,p.name product_name,u.full_name FROM stock_movements sm JOIN products p ON p.id=sm.product_id LEFT JOIN users u ON u.id=sm.user_id ORDER BY sm.id DESC LIMIT 12')->fetchAll();require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1>Inventory</h1><p>Monitor stock levels and track every adjustment.</p></div></div><div class="panel"><form class="toolbar" method="get"><input name="q" placeholder="Search product or SKU…" value="<?=e($q)?>"><select name="status"><option value="">All stock levels</option><option value="low" <?=$status==='low'?'selected':''?>>Low stock</option><option value="out" <?=$status==='out'?'selected':''?>>Out of stock</option></select><button class="btn">Filter</button><a class="btn" href="index.php">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>On hand</th><th>Minimum</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">No inventory items found.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['sku'])?></td><td><?=e($r['category_name'])?></td><td><?=$r['quantity']?></td><td><?=$r['minimum_stock']?></td><td><span class="badge <?=$r['quantity']==0?'danger':($r['quantity']<=$r['minimum_stock']?'warning':'success')?>"><?=$r['quantity']==0?'Out of stock':($r['quantity']<=$r['minimum_stock']?'Low stock':'In stock')?></span></td><td><a class="btn small" href="adjust_stock.php?id=<?=$r['id']?>">Adjust</a> <a class="btn small" href="/shop-inventory-management/products/view.php?id=<?=$r['id']?>">History</a></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="panel space-top"><div class="panel-header"><div><h2>Recent stock movements</h2><p>Latest inventory activity</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Change</th><th>Reason</th><th>User</th></tr></thead><tbody><?php if(!$moves):?><tr><td colspan="5" class="empty">No movements recorded.</td></tr><?php else:foreach($moves as $m):?><tr><td><?=e($m['created_at'])?></td><td><?=e($m['product_name'])?></td><td class="<?=$m['quantity_change']>0?'text-green':'text-red'?>"><?=$m['quantity_change']>0?'+':''?><?=$m['quantity_change']?></td><td><?=e($m['reason'])?></td><td><?=e($m['full_name']??'System')?></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
